using V=arkjson::Value;
static int checks=0;
static void check(bool b,const char* why){++checks;if(!b)throw std::runtime_error(why);}
static V json(const std::string& s){V v;check(arkjson::parse(s,v),"JSON");return v;}
static V& member(V& v,const char* k){for(auto& x:v.obj)if(x.first==k)return x.second;throw std::runtime_error(k);}
static V& data(V& p,const char* id){for(auto& n:member(p,"nodes").arr)if(n.find("id")->str==id)return member(n,"data");throw std::runtime_error(id);}
static void rejects(const std::function<void()>& f,const char* why){bool bad=false;try{f();}catch(const std::exception&){bad=true;}check(bad,why);}
static V payload(V v){check(!v.find("isError")->b,v.find("structuredContent")->dump().c_str());return *v.find("structuredContent");}
static ark::AgentSession fixture(){ark::AgentSession s;payload(s.call("doc_apply",json(R"({"commands":[{"op":"feature.add","type":"box","name":"Synthetic source","p":{"dx":20,"dy":20,"dz":4}}]})")));auto& b=s.document.evalBodies.front();b.nativeData=json(R"({"brep_base64":"synthetic-custody-fixture","report":{"brep_valid":true,"solids":1}})");return s;}
static V retain(ark::AgentSession& s,V p){V args=V::makeObj(),commands=V::makeArr(),command=V::makeObj();command.set("op",V::makeStr("manufacturing.set"));command.set("plan",p);commands.arr.push_back(command);args.set("commands",commands);args.set("expected_revision",V::makeNum(s.revision));return s.call("doc_apply",args);}
