    check(!study.receipt.find("blocked")->b,"safe plunge unexpectedly blocked");check(study.receipt.find("removed_volume_mm3")->num==48,"analytic voxel-centre plunge volume");check(study.stockCells.size()==1600&&study.remainingStock.size()==1552,"stock cells retained");check(ark::documentToJson(session.document)==authored&&session.revision==revision,"simulation authored CAD");check(study.receipt.find("cost")->find("available")->b,"declared cost rates unavailable");check(!study.receipt.find("manufacturing_qualified")->b,"simulation falsely qualified manufacturing");
    auto cached=ark::simulateManufacturing(session.document,revision,"CNC setup");check(cached.receipt.find("cache_hit")->b&&cached.receipt.find("result_id")->str==study.receipt.find("result_id")->str,"source-bound study was not shared from cache");
    V roundtrip;check(arkjson::parse(authored,roundtrip)&&roundtrip.find("version")->num==53,"conditional format 53");ark::Document reopened;std::string why;check(ark::documentFromJson(authored,reopened,&why),why.c_str());check(reopened.manufacturingPlans.arr.size()==1,"plan persistence");
    V bad=p;data(bad,"setup").set("machine",V::makeStr("absent"));check(retain(session,bad).find("isError")->b&&session.revision==revision&&ark::documentToJson(session.document)==authored,"missing dependency did not reject atomically");
    bad=p;auto& nodes=member(bad,"nodes").arr;nodes.front().set("depends_on",json("[\"op1\"]"));check(retain(session,bad).find("isError")->b&&session.revision==revision,"dependency cycle accepted");
