    bad=p;data(bad,"vice").set("initially_clamped",V::makeBool(false));payload(retain(session,bad));study=ark::simulateManufacturing(session.document,session.revision,"CNC setup");check(study.receipt.find("blocked")->b&&study.receipt.find("removed_volume_mm3")->num==0,"unclamped stock was machined");
    bad=p;data(bad,"vice").set("min_mm",json("[8,8,0]"));data(bad,"vice").set("size_mm",json("[4,4,10]"));payload(retain(session,bad));check(ark::simulateManufacturing(session.document,session.revision,"CNC setup").receipt.find("blocked")->b,"fixture collision missed");
    bad=p;data(bad,"column").set("min_mm",json("[0,0,0]"));data(bad,"column").set("size_mm",json("[40,30,300]"));payload(retain(session,bad));check(ark::simulateManufacturing(session.document,session.revision,"CNC setup").receipt.dump().find("MACHINE_BODY_ENVELOPE")!=std::string::npos,"declared carriage collision pair missed");
    bad=p;data(bad,"vice").set("initially_clamped",V::makeBool(false));V clamp=json(R"({"id":"clamp","kind":"operation","data":{"setup":"setup","type":"clamp","fixture":"vice","duration_s":3}})");member(bad,"nodes").arr.push_back(clamp);for(auto& n:member(bad,"nodes").arr)if(n.find("id")->str=="op1")n.set("depends_on",json("[\"clamp\"]"));payload(retain(session,bad));check(!ark::simulateManufacturing(session.document,session.revision,"CNC setup").receipt.find("blocked")->b,"ordered clamp event did not enable cutting");
    for(const char* code:{"G41\n","G1 X1 #4\n","G90 G91\n","G2 X10 Y10 I0 J0\n","G20 G21\n"}){bad=p;data(bad,"op1").set("gcode",V::makeStr(code));payload(retain(session,bad));rejects([&]{ark::simulateManufacturing(session.document,session.revision,"CNC setup");},"unsupported/ambiguous program accepted");}
