    data(face,"op1").set("stepdown_mm",V::makeNum(1e-30));payload(retain(session,face));rejects([&]{ark::simulateManufacturing(session.document,session.revision,"CNC setup");},"extreme CAM subdivisions did not reject before integer conversion");
    const auto programPath=std::filesystem::temp_directory_path()/("ark-mfg-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count())+".nc");const std::string code="G21 G90 G17 G94\nG0 X0 Y0 Z200\nM30\n";{std::ofstream f(programPath,std::ios::binary);f<<code;}
    bad=p;auto& external=data(bad,"op1");external.obj.erase(std::remove_if(external.obj.begin(),external.obj.end(),[](const auto& f){return f.first=="gcode";}),external.obj.end());external.set("source_path",V::makeStr(programPath.string()));external.set("source_sha256",V::makeStr(ark::iterationSha256(code)));payload(retain(session,bad));ark::simulateManufacturing(session.document,session.revision,"CNC setup");{std::ofstream f(programPath,std::ios::app);f<<"; changed bytes\n";}rejects([&]{ark::simulateManufacturing(session.document,session.revision,"CNC setup");},"cache accepted modified external program bytes");std::filesystem::remove(programPath);
